import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:]))

    if all(x == 1 for x in a):
        print("NO")
    else:
        print("YES")
        if n == 1:
            print("0")
        else:
            result = ""
            for i in range(n - 1):
                result += f"({a[i]}->"
            result += f"{a[-1]}"
            result += ")" * (n - 1)
            print(result)

if __name__ == "__main__":
    main()
